-- ── Verification ───────────────────────────────────────────────────────────
SELECT prep_field, topic, difficulty, type, COUNT(*) AS question_count
FROM questions
GROUP BY prep_field, topic, difficulty, type
ORDER BY prep_field, topic, difficulty, type;
